182: // ── LLM availability check (3s timeout, uses chat/completions) ──────
183: async function checkLLMAvailability(url: string, key: string): Promise<boolean> {
184:   if (key === 'sk-placeholder') return false;
185:   try {
186:     const controller = new AbortController();
187:     const timeout = setTimeout(() => controller.abort(), 3000);
188:     const res = await fetch(`${url}/chat/completions`, {
189:       method: 'POST',
190:       headers: {
191:         'Authorization': `Bearer ${key}`,
192:         'Content-Type': 'application/json',
193:       },
194:       body: JSON.stringify({
195:         model: model,
196:         messages: [{ role: 'user', content: 'ping' }],
197:         max_tokens: 1,
198:       }),
199:       signal: controller.signal,
200:     });
201:     clearTimeout(timeout);
202:     if (res.ok) return true;
203:     // 401/403 = invalid key → unavailable
204:     if (res.status === 401 || res.status === 403) return false;
205:     // 4xx (except 429 rate limit) = misconfigured endpoint → unavailable
206:     if (res.status >= 400 && res.status < 500 && res.status !== 429) return false;
207:     // 5xx or other = might be transient, treat as available
208:     return true;
209:   } catch {
210:     return false;
211:   }
212: }
