449: // ── AgenticOrchestrator encounter handler (all modalities) ────────────
450: async function runAgenticEncounter(
451:   encounter: ScheduledEncounter,
452:   sig: Significator,
453:   world: WorldState,
454:   history: ConsequenceRecord[],
455:   responsesPool?: number[],
456:   consecutivePasses?: Map<string, number>,
457: ): Promise<{
458:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
459:   response: PlayerResponse;
460:   narrativeSummary: string;
461: }> {
462:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
463:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
464: 
465:   // If --line/--stage/--modality forcing is active, override the encounter
466:   let forcedEncounter = encounter;
467:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
468:     const forcedLine = FORCE_LINE ?? encLine;
469:     const forcedStage = FORCE_STAGE ?? encStage;
470:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
471:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
472:     if (forcedModule) {
473:       forcedEncounter = {
474:         ...encounter,
475:         moduleRef: `${forcedLine}:${forcedStage}`,
476:         modality: forcedModality,
477:         targetLines: [forcedLine],
478:         stage: forcedStage,
479:       };
480:     }
481:   }
482: 
483:   const uiHandler: AgenticUIHandler = {
484:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
485:       const answers: UserAnswer[] = [];
486: 
487:       for (const q of params.questions) {
488:         if (!JSON_MODE) {
489:           const mod = forcedEncounter.modality;
490:           let modHeader = '';
491: 
492:           switch (mod) {
493:             case 'Deterministic':
494:               modHeader = `${C.bold}${C.red}⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)${C.reset}\n`;
495:               break;
496:             case 'LanguageReflective':
497:               modHeader = `${C.bold}${C.blue}🧘 [REFLECTION BEAT] • Tune in to your inner state •${C.reset}\n`;
498:               break;
499:             case 'ScenarioChoice':
500:               modHeader = `${C.bold}${C.yellow}🔀 [DECISION CROSSROADS] • A path diverges •${C.reset}\n`;
501:               break;
502:             case 'Embodied':
503:               modHeader = `${C.bold}${C.green}💓 [SOMATIC SCAN] • Focus on body sensation •${C.reset}\n`;
504:               break;
505:             case 'Strategic':
506:               modHeader = `${C.bold}${C.magenta}♟️ [TACTICAL WAR-TABLE] • Assess constraints •${C.reset}\n`;
507:               break;
508:             case 'SocialCooperative':
509:               modHeader = `${C.bold}${C.cyan}🤝 [DIPLOMACY] • Navigating connection •${C.reset}\n`;
510:               break;
511:             case 'ImmersiveRPG':
512:               modHeader = `${C.bold}${C.yellow}📖 [NARRATIVE SCENE] • The story unfolds •${C.reset}\n`;
513:               break;
514:             default:
515:               modHeader = `${C.bold}${C.dim}[${mod.toUpperCase()}]${C.reset}\n`;
516:           }
517: 
518:           console.log(`\n  ${modHeader}  ${C.magenta}[${q.header}]${C.reset}`);
519:           console.log(`  ${C.bold}${q.question}${C.reset}`);
520:           if (q.options?.length) {
521:             for (let i = 0; i < q.options.length; i++) {
522:               const opt = q.options[i];
523:               console.log(`    ${C.cyan}[${i + 1}]${C.reset} ${opt.label} — ${opt.description}`);
524:             }
525:           }
526:         }
527: 
528:         emitEvent('ask_user', {
529:           header: q.header,
530:           question: q.question,
531:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
532:           allowWriteIn: q.allowWriteIn,
533:         });
534: 
535:         if (HEADLESS) {
536:           // Use forced responses pool if provided (one index per question, consumed sequentially)
537:           let selectedIdx: number;
538:           if (responsesPool && responsesPool.length > 0) {
539:             const forcedIdx = responsesPool.shift()!;
540:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
541:               selectedIdx = forcedIdx - 1;
542:             } else {
543:               selectedIdx = 0;
544:             }
545:           } else {
546:             // Vary selection to probe different shadow patterns:
547:             // Cycle through options to ensure shadow detection has varied input
548:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
549:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
550:           }
551:           const selectedOpt = q.options?.[selectedIdx];
552:           const selectedLabel = selectedOpt?.label ?? '';
553: 
554:           // Shadow keyword injection for testing — randomly inject (10% chance)
555:           // to allow MOST encounters to pass and demonstrate altitude shifts.
556:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
557:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
558:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
559:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
560: 
561:           if (writeInShadow) {
562:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
563:           } else {
564:             answers.push({ selectedLabels: [selectedLabel] });
565:           }
566:         } else {
567:           const promptText = q.multiSelect
568:             ? '\n  Select (comma-separated): '
569:             : '\n  Select: ';
570:           const answer = await ask(promptText);
571:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
572:           const selectedLabels = selections
573:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
574:             .map(n => q.options![n - 1]!.label);
575: 
576:           // Determine if input is a simple numeric choice from the options
577:           let isSimpleNumericChoice = false;
578:           if (q.options?.length && answer.trim()) {
579:             const parts = answer.split(',').map(s => s.trim());
580:             isSimpleNumericChoice = parts.every(part => {
581:               const num = parseInt(part, 10);
582:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
583:             });
584:           }
585: 
586:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
587:             // Only populate writeInValue if it's NOT a simple numeric choice
588:             if (!isSimpleNumericChoice && answer.trim()) {
589:               answers.push({ selectedLabels, writeInValue: answer.trim() });
590:             } else {
591:               answers.push({ selectedLabels });
592:             }
593:           } else {
594:             answers.push({ selectedLabels });
595:           }
596:         }
597:       }
598: 
599:       return { answers };
600:     }
601:   };
602: 
603:   // Always route through AgenticOrchestrator — it handles LLM + fallback internally
604:   // Look up the assessment module from the registry to inject into the LLM context
605:   const baseModule = modRegistry?.get(encLine, encStage);
606: 
607:   // Build ConceptDraftIndex from the module registry so the LLM sees module metadata
608:   const conceptModules: Record<string, any> = {};
609:   if (modRegistry) {
610:     for (const m of modRegistry.getAll()) {
611:       const key = `${m.line.toLowerCase()}:${m.stage.toLowerCase()}`;
612:       conceptModules[key] = {
613:         line: m.line,
614:         stage: m.stage,
615:         title: `${m.line} ${m.stage} Module`,
616:         modalities: m.tasks.map(t => t.type === 'llm_dialogue' ? 'LanguageReflective' as const : 'Deterministic' as const),
617:       };
618:     }
619:   }
620: 
621:   const orchestrator = new AgenticOrchestrator({
622:     encounter: forcedEncounter,
623:     significator: sig,
624:     world,
625:     history,
626:     conceptIndex: { modules: conceptModules },
627:     uiHandler,
628:     module: modRegistry?.get(FORCE_LINE ?? encLine, FORCE_STAGE ?? encStage) ?? baseModule,
629:     noLlm: !LLM_ACTIVE,
630:     forceShadow: FORCE_SHADOW,
631:     consecutivePasses,
632:   });
633: 
634:   const outcome = await orchestrator.run();
635: 
636:   // Build a PlayerResponse from the orchestrator's consequence record
637:   const cr = outcome.consequenceRecord;
638:   const response: PlayerResponse = {
639:     encounterId: encounter.id,
640:     energeticDirection: cr.polarityTrace.energeticDirection,
641:     driveDirectionality: cr.polarityTrace.driveDirectionality,
642:     stageOrientation: cr.polarityTrace.stageOrientation,
643:     sourceOfNourishment: cr.polarityTrace.sourceOfNourishment,
644:     shadowSurfaced: cr.shadowSurfaced,
645:     shadowResolvedId: cr.shadowResolved,
646:     narrativeSummary: outcome.narrativeSummary,
647:   };
648: 
649:   return { outcome, response, narrativeSummary: outcome.narrativeSummary };
650: }
