const mode = getVal('mode') ?? (flags.has('--mode') ? args[args.indexOf('--mode') + 1] : 'full') ?? 'full';
const encounterCount = parseInt(getVal('encounters') ?? String(fileConfig.session?.defaultEncounters ?? 20), 10);

