const FORCE_SHADOW = opts.forceShadow as string | undefined;
const FORCE_RESPONSES = undefined; // ponytail: --responses removed, wasn't in commander spec
const NEW_GAME = opts.newGame ?? false;

// ── Helpers ───────────────────────────────────────────────────────────
